// MIT. Conditions from original runtime snapshots; no parallel traffic collector.
import {randomUUID} from 'node:crypto';
import {activeIncident, kinds, merchantBinding} from './incident-config.mjs';
import {queueNotification, terminalNotification} from './notifications.mjs';
import {objectObservationSignals} from './object-observation.mjs';

const cumulative=['started','completed','responses','success','challenge','clientError','serverError','other','disconnected'];
const iso=now=>new Date(now).toISOString();
export function freshMerchant(config,merchant) {
  return {binding:merchantBinding(config,merchant),previous:null,lastSuccessAt:null,lastAttemptAt:null,
    lastCapture:null,captureState:'NO_CAPTURE',sessionsSeen:0,lastError:null,conditions:{}};
}
export function updateConfiguration(state,config,digest,env,now) {
  const merchants={};
  for(const merchant of config.merchants) {
    const old=state.merchants[merchant.id],binding=merchantBinding(config,merchant);
    merchants[merchant.id]=old?.binding===binding?old:freshMerchant(config,merchant);
  }
  for(const incident of state.incidents.filter(activeIncident)) {
    if(merchants[incident.merchantId]?.binding===incident.binding) continue;
    incident.status='RETIRED';incident.retiredReason='CONFIGURATION_CHANGED';
    incident.closedAt=iso(now);incident.updatedAt=iso(now);incident.revision++;
    // Bind this final old-source transition to its original configuration.
    queueNotification(state,incident,'RETIRED',env,now);
  }
  state.config=config;state.configHash=digest;state.configRevision++;
  state.merchants=merchants;
}
function signalsFor(config,merchant,observation,previous,now) {
  if(merchant.object)return objectObservationSignals(merchant,observation,now,previous);
  const packet=observation.packet;
  if(!packet) return {signals:{ENDPOINT_UNAVAILABLE:{bad:true,values:{}}},error:observation.error};
  const o=packet.report.observation,captured=Date.parse(o.capturedAt),start=Date.parse(o.startedAt);
  const same=previous?.sessionId===o.sessionId;
  if(start>captured || captured>now+5000 || now-captured>30_000 ||
      (same&&(previous.startedAt!==o.startedAt||captured<Date.parse(previous.capturedAt)||
        cumulative.some(key=>o.totals[key]<previous.totals[key])||o.observerErrors<previous.observerErrors)))
    return {signals:{ENDPOINT_UNAVAILABLE:{bad:true,values:{}}},error:'SOURCE_COUNTER_OR_CLOCK_INVALID'};
  const minute=Math.floor(captured/60_000)*60_000;
  const windowStart=minute-(config.windowMinutes-1)*60_000;
  const buckets=o.minutes.filter(row=>Date.parse(row.minute)>=windowStart&&Date.parse(row.minute)<=minute);
  if(buckets.length!==config.windowMinutes || new Set(buckets.map(row=>row.minute)).size!==buckets.length ||
      buckets.some(row=>Date.parse(row.minute)%60_000!==0))
    return {signals:{ENDPOINT_UNAVAILABLE:{bad:true,values:{}}},error:'SOURCE_MINUTE_WINDOW_INVALID'};
  const totals=buckets.reduce((sum,row)=>{for(const key of ['responses','completed','serverError','disconnected'])sum[key]+=row[key];return sum;},
    {responses:0,completed:0,serverError:0,disconnected:0});
  const complete=o.attached&&o.observerErrors===0&&start<=windowStart;
  const traffic=(threshold,failures,requests)=>{
    if(!threshold)return {bad:null,values:{}};
    const percent=requests?failures*100/requests:0;
    const bad=failures>=threshold.minimum&&percent>=threshold.percent;
    return {bad:bad?true:complete?false:null,values:{requests,failures,percent,
      minimum:threshold.minimum,thresholdPercent:threshold.percent,windowMinutes:config.windowMinutes}};
  };
  const signals={ENDPOINT_UNAVAILABLE:{bad:false,values:{}},
    OBSERVER_INCOMPLETE:{bad:!o.attached||o.observerErrors>0,values:{observerErrors:o.observerErrors}},
    HTTP_5XX:traffic(config.httpErrors,totals.serverError,totals.responses),
    DISCONNECTED:traffic(config.disconnects,totals.disconnected,totals.completed)};
  if(merchant.delivery) {
    const d=observation.delivery;
    const available=d?.available===true;
    signals.DELIVERY_UNAVAILABLE={bad:available?false:merchant.delivery.required?true:null,values:{}};
    signals.DELIVERY_BACKLOG={bad:available?d.pending>0&&d.oldestPendingSeconds!==null&&
      d.oldestPendingSeconds>=merchant.delivery.oldestPendingSeconds:null,
      values:available?{pending:d.pending,oldestPendingSeconds:d.oldestPendingSeconds ?? 0,
        thresholdSeconds:merchant.delivery.oldestPendingSeconds}:{}};
    signals.DELIVERY_EXHAUSTED={bad:available?d.exhausted>=merchant.delivery.exhausted:null,
      values:available?{exhausted:d.exhausted,minimum:merchant.delivery.exhausted}:{}};
  }
  return {signals,packet,previous:{sessionId:o.sessionId,startedAt:o.startedAt,capturedAt:o.capturedAt,
    observerErrors:o.observerErrors,totals:Object.fromEntries(cumulative.map(key=>[key,o.totals[key]]))},
    window:{from:iso(windowStart),through:o.capturedAt,complete,sessionStartedAt:o.startedAt},error:null};
}
export function validateDelivery(value,now) {
  if(value?.schema!=='stellar-forge.sf98.operator-delivery.v1'||typeof value.available!=='boolean')
    throw new Error('SF93_DELIVERY_SOURCE_INVALID');
  if(!value.available)return {available:false};
  const fields=['originalNativeEvents','webhookAccepted','pending','retryDue','retryWaiting','exhausted'];
  if(fields.some(key=>!Number.isSafeInteger(value[key])||value[key]<0)||
      value.originalNativeEvents!==value.webhookAccepted+value.pending+value.exhausted||
      value.retryDue+value.retryWaiting!==value.pending ||
      !(value.oldestPendingSeconds===null||Number.isSafeInteger(value.oldestPendingSeconds)&&value.oldestPendingSeconds>=0)||
      !Number.isFinite(Date.parse(value.capturedAt))||Date.parse(value.capturedAt)>now+5000||
      now-Date.parse(value.capturedAt)>30_000) throw new Error('SF93_DELIVERY_SOURCE_INVALID');
  return {available:true,capturedAt:value.capturedAt,
    ...Object.fromEntries(fields.map(key=>[key,value[key]])),oldestPendingSeconds:value.oldestPendingSeconds};
}
export async function applyObservation(state,merchant,observation,saveCapture,env,now) {
  const row=state.merchants[merchant.id];
  const result=signalsFor(state.config,merchant,observation,row.previous,now);
  row.lastAttemptAt=iso(now);row.lastError=result.error ?? null;
  if(merchant.object&&result.packet?.object)row.objectObservation={observedAt:result.packet.object.generatedAt,
    ...result.packet.object.summary,poll:{appliedAt:iso(now),fresh:result.fresh===true,
      successful:result.successful===true,reason:result.error??null}};
  let currentCapture;
  const capture=async()=>{
    if(currentCapture!==undefined)return currentCapture;
    currentCapture=result.packet?await saveCapture(result.packet):null;
    row.captureState=currentCapture?'CAPTURED':result.packet?'STORAGE_LIMIT':'SOURCE_UNAVAILABLE';
    if(currentCapture)row.lastCapture=currentCapture;
    return currentCapture;
  };
  if(result.packet&&(!merchant.object||result.successful===true)) {
    const changedSession=row.previous?.sessionId!==result.previous.sessionId;
    if(changedSession) {
      row.sessionsSeen++;
      // A new native observer starts a new history. No cumulative subtraction.
      for(const condition of Object.values(row.conditions)) {condition.badStreak=0;condition.goodStreak=0;}
    }
    row.previous=result.previous;row.lastSuccessAt=iso(now);row.window=result.window;
    if(!row.lastCapture||changedSession||now-Date.parse(row.lastCapture.generatedAt)>=state.config.captureEveryMs) await capture();
  } else if(result.packet) {
    // Retain incomplete/stale Object evidence without replacing the last
    // successful native observation or advancing a healthy recovery poll.
    await capture();
  }
  for(const kind of kinds) {
    const condition=row.conditions[kind]??={badStreak:0,goodStreak:0,lastState:'UNKNOWN',incidentId:null};
    const signal=result.signals[kind]??{bad:null,values:{}};
    condition.lastState=signal.bad===null?'UNKNOWN':signal.bad?'FAILING':'CLEAR';
    if(signal.bad===null) {condition.badStreak=0;condition.goodStreak=0;continue;}
    condition.badStreak=signal.bad?Math.min(100,condition.badStreak+1):0;
    condition.goodStreak=signal.bad?0:Math.min(100,condition.goodStreak+1);
    let incident=state.incidents.find(item=>item.id===condition.incidentId&&activeIncident(item));
    if(signal.bad) {
      if(!incident&&condition.badStreak>=(signal.openAfter??state.config.failurePolls)) {
        const before=result.packet?await capture():row.lastCapture;
        incident={id:randomUUID(),merchantId:merchant.id,merchantLabel:merchant.label,binding:row.binding,kind,
          status:'OPEN',revision:1,openedAt:iso(now),updatedAt:iso(now),lastObservedAt:iso(now),closedAt:null,
          sessionId:row.previous?.sessionId ?? null,lastSessionId:row.previous?.sessionId ?? null,
          signal:{...signal.values,consecutivePolls:condition.badStreak},
          acknowledgment:null,beforeCapture:before ?? null,afterCapture:null,notificationState:null};
        state.incidents.push(incident);condition.incidentId=incident.id;
        queueNotification(state,incident,'OPENED',env,now);
      } else if(incident) {
        incident.lastObservedAt=iso(now);incident.signal={...signal.values,consecutivePolls:condition.badStreak};
        incident.lastSessionId=row.previous?.sessionId ?? null;
      }
    } else if(incident&&condition.goodStreak>=state.config.recoveryPolls) {
      incident.status='RECOVERED';incident.closedAt=iso(now);incident.updatedAt=iso(now);incident.revision++;
      incident.afterCapture=await capture();incident.recoverySessionId=row.previous?.sessionId ?? null;
      incident.recoverySignal={...signal.values,consecutivePolls:condition.goodStreak};
      queueNotification(state,incident,'RECOVERED',env,now);condition.incidentId=null;
    }
  }
}
export function pruneRecords(state,now) {
  const keepEvents=new Set(state.notifications.filter(event=>!terminalNotification(event)).map(event=>event.id));
  state.notifications.filter(terminalNotification).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))
    .slice(0,state.config.retention.notifications).forEach(event=>keepEvents.add(event.id));
  state.notifications=state.notifications.filter(event=>keepEvents.has(event.id));
  const protectedIds=new Set(state.notifications.filter(event=>!terminalNotification(event)).map(event=>event.incidentId));
  const cutoff=now-state.config.retention.closedDays*86_400_000;
  const closed=state.incidents.filter(item=>!activeIncident(item)&&Date.parse(item.closedAt)>=cutoff)
    .sort((a,b)=>b.closedAt.localeCompare(a.closedAt)).slice(0,state.config.retention.closedIncidents);
  const keep=new Set(closed.map(item=>item.id));
  state.incidents=state.incidents.filter(item=>activeIncident(item)||protectedIds.has(item.id)||keep.has(item.id));
  const ids=new Set(state.incidents.map(item=>item.id));
  state.notifications=state.notifications.filter(event=>ids.has(event.incidentId));
}

// MIT. Exact source-edition comparison for the original QBO/Xero accountant plans.
import {qboCanonical,qboHash,validateQboPlan} from './qbo.mjs';
import {validateQboCompany} from './qbo-company.mjs';
import {isQboBuyerPlan} from './qbo-buyer.mjs';
import {validateXeroContext,validateXeroPlan} from './xero.mjs';

export const SOURCE_CHANGE_SCHEMA='stellar-forge.accounting-source-change.v1';
export const changeCanonical=qboCanonical;
export const changeHash=value=>qboHash(typeof value==='string'||Buffer.isBuffer(value)?value:qboCanonical(value));
export const changeClone=value=>structuredClone(value);
export function changeCheck(ok,code,message,status=400){if(!ok)throw Object.assign(new Error(message),{code,status});}
export function changeId(value){
  changeCheck(typeof value==='string'&&/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(value),
    'SOURCE_CHANGE_ID','Use the original lower-case UUID.');return value;
}
export function changeText(value,label,max=2000){
  changeCheck(typeof value==='string'&&value.trim().length>0&&value.length<=max&&!/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/.test(value),
    'SOURCE_CHANGE_FIELD','Provide '+label+' within '+max+' characters.');return value;
}
export function changeKind(value){changeCheck(['qbo','xero'].includes(value),'SOURCE_CHANGE_KIND','Choose QuickBooks or Xero.');return value;}
const same=(a,b)=>qboCanonical(a)===qboCanonical(b);
const plain=value=>value!==null&&typeof value==='object'&&!Array.isArray(value);

export function sourceEdition(kind,value){
  changeKind(kind);
  if(kind==='qbo'){
    validateQboCompany(value);
    return {kind,sha256:value.integrity.sha256,company:{id:value.realmId,name:value.companyName,baseCurrency:value.baseCurrency,
      multiCurrencyEnabled:value.multiCurrencyEnabled},accounts:value.accounts.map(row=>({id:row.value,code:null,name:row.name,
      eligible:row.selectable,status:row.Active?'ACTIVE':'INACTIVE',type:row.AccountType,currency:row.CurrencyRef?.value??value.baseCurrency,
      reasons:changeClone(row.reasons??[])}))};
  }
  validateXeroContext(value);
  return {kind,sha256:value.sha256,company:{id:value.tenantId,name:value.organization.name,
    baseCurrency:value.organization.baseCurrency,isDemoCompany:value.organization.isDemoCompany,status:value.organization.status},
    accounts:value.accounts.map(row=>({id:row.id,code:row.code,name:row.name,eligible:row.eligible,
      status:row.status,type:row.type,systemAccount:row.systemAccount}))};
}
export function planIdentity(kind,plan){
  if(changeKind(kind)==='qbo'){validateQboPlan(plan);return plan.integrity.sha256;}
  validateXeroPlan(plan);return plan.sha256;
}
export function compareSourceEditions(kind,plan,before,after){
  planIdentity(kind,plan);const left=sourceEdition(kind,before),right=sourceEdition(kind,after);
  changeCheck(left.company.id===right.company.id,'SOURCE_CHANGE_COMPANY','A chart change must retain the same original company or tenant.',409);
  if(kind==='xero')changeCheck(left.company.isDemoCompany===right.company.isDemoCompany,'SOURCE_CHANGE_COMPANY',
    'Preserve the original demo/books organization identity.',409);
  const uses=new Map(),use=(id,sourceId,side)=>{const rows=uses.get(id)??[];rows.push({sourceId,side});uses.set(id,rows);};
  for(const row of kind==='qbo'?plan.rows:plan.entries){
    const sourceId=kind==='qbo'?row.rowId:row.id;
    use(kind==='qbo'?row.debitAccount.value:row.debitAccount.id,sourceId,'debit');
    use(kind==='qbo'?row.creditAccount.value:row.creditAccount.id,sourceId,'credit');
  }
  const a=new Map(left.accounts.map(row=>[row.id,row])),b=new Map(right.accounts.map(row=>[row.id,row]));
  const accounts=[...new Set([...a.keys(),...b.keys()])].sort().map(id=>{
    const before=a.get(id)??null,after=b.get(id)??null;
    const fields=before&&after?[...new Set([...Object.keys(before),...Object.keys(after)])].sort().filter(key=>!same(before[key]??null,after[key]??null)):[];
    return {id,change:!before?'added':!after?'removed':fields.length?'changed':'unchanged',before,after,fields,usedBy:uses.get(id)??[]};
  });
  const companyChanges=[...new Set([...Object.keys(left.company),...Object.keys(right.company)])].sort()
    .filter(field=>!same(left.company[field]??null,right.company[field]??null))
    .map(field=>({field,before:left.company[field]??null,after:right.company[field]??null}));
  const body={schema:SOURCE_CHANGE_SCHEMA,kind,predecessorSha256:planIdentity(kind,plan),beforeSha256:left.sha256,afterSha256:right.sha256,
    sourceChanged:left.sha256!==right.sha256,companyChanges,accounts,
    summary:{added:accounts.filter(row=>row.change==='added').length,removed:accounts.filter(row=>row.change==='removed').length,
      changed:accounts.filter(row=>row.change==='changed').length,unchanged:accounts.filter(row=>row.change==='unchanged').length,
      usedChanged:accounts.filter(row=>row.usedBy.length&&row.change!=='unchanged').length,
      usedUnavailable:accounts.filter(row=>row.usedBy.length&&!row.after?.eligible).length,
      currencyChanged:left.company.baseCurrency!==right.company.baseCurrency}};
  return {...body,sha256:changeHash(body)};
}
export function successorDefaults(kind,plan,target){
  planIdentity(kind,plan);const after=sourceEdition(kind,target),accounts=new Map(after.accounts.map(row=>[row.id,row]));
  const selected=(id,key)=>{const row=accounts.get(id);return row?.eligible?row[key]:'';};
  const name=(plan.name+' — chart update').slice(0,160);
  if(kind==='qbo')return {name,txnDate:plan.txnDate,docNumber:null,
    ...(isQboBuyerPlan(plan)?{sourceKind:plan.sourceKind,valuationBasis:plan.valuationBasis}:{}),rows:[
    ...plan.rows.map(row=>({rowId:row.rowId,amount:row.amount,
      debitAccount:{value:selected(row.debitAccount.value,'id')},creditAccount:{value:selected(row.creditAccount.value,'id')},
      description:row.description,...(isQboBuyerPlan(plan)?{decision:'include',valuationNote:row.valuationNote}:{})})),
    ...(isQboBuyerPlan(plan)?plan.excluded.map(row=>({rowId:row.rowId,decision:'exclude',reason:row.reason})):[])]};
  return {name,valuationBasis:plan.valuationBasis,entries:[
    ...plan.entries.map(row=>({componentId:row.id,decision:'include',date:row.date,amount:row.amount,
      debitAccountCode:selected(row.debitAccount.id,'code'),creditAccountCode:selected(row.creditAccount.id,'code'),
      valuationNote:row.valuationNote,description:row.description})),
    ...plan.excluded.map(row=>({componentId:row.id,decision:'exclude',reason:row.reason}))]};
}
export function assertSameEconomicSource(kind,before,after){
  planIdentity(kind,before);planIdentity(kind,after);
  changeCheck(before.id!==after.id,'SOURCE_CHANGE_SUCCESSOR_ID','Use a new retained UUID for the successor.');
  if(kind==='qbo'){
    changeCheck(before.handoffId===after.handoffId&&before.handoffSha256===after.handoffSha256&&
      before.realmId===after.realmId&&before.environment===after.environment,'SOURCE_CHANGE_ECONOMIC_SOURCE',
      'Preserve this plan’s exact handoff, company and environment.',409);
    changeCheck(isQboBuyerPlan(before)===isQboBuyerPlan(after),'SOURCE_CHANGE_ECONOMIC_SOURCE','Preserve the original source kind.',409);
    if(isQboBuyerPlan(before)){
      const project=plan=>plan.rows.map(row=>Object.fromEntries(Object.entries(row).filter(([key])=>
        !['amount','amountMinor','debitAccount','creditAccount','valuationNote','description'].includes(key)))).sort((a,b)=>a.rowId.localeCompare(b.rowId));
      const excluded=plan=>[...plan.excluded].sort((a,b)=>a.rowId.localeCompare(b.rowId));
      changeCheck(same(before.source,after.source)&&same(project(before),project(after))&&same(excluded(before),excluded(after)),
        'SOURCE_CHANGE_ECONOMIC_SOURCE','Keep every included buyer allocation and original exclusion; change only explicit accounts and valuations.',409);
      return true;
    }
    const project=plan=>plan.rows.map(row=>({rowId:row.rowId,eventId:row.eventId,sourceRowSha256:row.sourceRowSha256,
      assignmentSha256:row.assignmentSha256,sourceNetwork:row.sourceNetwork,sourceAmountAtomic:row.sourceAmountAtomic,
      sourceLabel:row.sourceLabel,sourceAdjustments:row.sourceAdjustments})).sort((a,b)=>a.rowId.localeCompare(b.rowId));
    changeCheck(same(project(before),project(after)),'SOURCE_CHANGE_ECONOMIC_SOURCE',
      'A chart replacement keeps every selected original economic event and its accountant assignment.',409);
  }else{
    changeCheck(same(before.source,after.source)&&same(before.baseline,after.baseline)&&before.context.tenantId===after.context.tenantId&&
      before.purpose===after.purpose&&before.showOnCashBasisReports===after.showOnCashBasisReports,
      'SOURCE_CHANGE_ECONOMIC_SOURCE','Preserve the exact handoff, accountant baseline, tenant and original journal treatment.',409);
    const project=plan=>plan.entries.map(row=>Object.fromEntries(Object.entries(row).filter(([key])=>
      !['date','amount','debitAccount','creditAccount','valuationNote','description'].includes(key)))).sort((a,b)=>a.id.localeCompare(b.id));
    const excluded=plan=>[...plan.excluded].sort((a,b)=>a.id.localeCompare(b.id));
    changeCheck(same(project(before),project(after))&&same(excluded(before),excluded(after)),
      'SOURCE_CHANGE_ECONOMIC_SOURCE','Keep every included component and every original exclusion; change only explicit mappings and valuations.',409);
  }
  return true;
}
export function successorRequest(kind,previous,target,input,{accountantRevisionId=null}={}){
  changeCheck(plain(input),'SOURCE_CHANGE_REQUEST','Provide the reviewed successor fields.');
  changeId(input.id);changeText(input.name,'the successor name',160);changeText(input.actor,'the operator',1000);
  changeCheck(typeof input.createdAt==='string'&&Number.isFinite(Date.parse(input.createdAt))&&new Date(input.createdAt).toISOString()===input.createdAt,
    'SOURCE_CHANGE_CREATED_AT','Retain the exact ISO timestamp assigned to this successor.');
  if(kind==='qbo')return {id:input.id,name:input.name,actor:input.actor,createdAt:input.createdAt,handoffId:previous.handoffId,
    expectedParentId:accountantRevisionId,realmId:previous.realmId,companyName:target.companyName,baseCurrency:target.baseCurrency,
    environment:previous.environment,txnDate:input.txnDate,docNumber:input.docNumber??null,rows:changeClone(input.rows),
    companySnapshot:changeClone(target),...(isQboBuyerPlan(previous)?{valuationBasis:input.valuationBasis}:{})};
  return {id:input.id,name:input.name,actor:input.actor,createdAt:input.createdAt,handoffId:previous.source.handoffId,
    contextId:target.id,accountantRevisionId:accountantRevisionId??'initial',entries:changeClone(input.entries),
    purpose:previous.purpose,valuationBasis:input.valuationBasis,showOnCashBasisReports:previous.showOnCashBasisReports};
}

// MIT. One Linux delivery writer per original SF98 outbox.
import { spawn } from 'node:child_process';
import { randomUUID } from 'node:crypto';
import { constants } from 'node:fs';
import { lstat, open, realpath } from 'node:fs/promises';
import { hostname } from 'node:os';
import { isAbsolute, join, resolve } from 'node:path';

const holders = new WeakMap();
const LOCK_NAME = '.sf98-delivery.lock';
const CONFLICT = 75;

async function privateDirectory(directory) {
  if (typeof directory !== 'string' || !isAbsolute(directory) ||
      directory === '/' || resolve(directory) !== directory ||
      await realpath(directory) !== directory) throw new Error('PRIVATE_OUTBOX_PATH_REQUIRED');
  const info = await lstat(directory);
  if (!info.isDirectory() || info.mode & 0o077) throw new Error('PRIVATE_OUTBOX_MODE_REQUIRED_0700');
}

async function lockFile(directory, create) {
  await privateDirectory(directory);
  const handle = await open(join(directory, LOCK_NAME), constants.O_RDWR |
    (create ? constants.O_CREAT : 0) | (constants.O_NOFOLLOW ?? 0), 0o600);
  try {
    const info = await handle.stat();
    if (!info.isFile() || info.nlink !== 1 || info.mode & 0o077)
      throw new Error('PRIVATE_DELIVERY_LOCK_REQUIRED_0600');
    return { handle, info };
  } catch (error) { await handle.close(); throw error; }
}

async function flock(handle) {
  if (process.platform !== 'linux') throw new Error('SF98_DELIVERY_REQUIRES_LINUX_FLOCK');
  // flock(2) belongs to the open file description. FD 3 is a dup of our still
  // open handle, so the kernel lock survives this short helper's exit and is
  // released by handle.close(), or automatically if this process is killed.
  return new Promise((resolvePromise, reject) => {
    const child = spawn('flock', ['--exclusive', '--nonblock',
      '--conflict-exit-code', String(CONFLICT), '3'], {
      stdio: ['ignore', 'ignore', 'ignore', handle.fd], shell: false,
    });
    const timer = setTimeout(() => child.kill('SIGKILL'), 5000);
    child.once('error', () => {
      clearTimeout(timer);
      reject(new Error('SF98_FLOCK_UNAVAILABLE_INSTALL_UTIL_LINUX'));
    });
    child.once('exit', code => {
      clearTimeout(timer);
      if (code === 0) resolvePromise(true);
      else if (code === CONFLICT) resolvePromise(false);
      else reject(new Error('SF98_DELIVERY_LOCK_HELPER_FAILED'));
    });
  });
}

export async function acquireDeliveryLease(directory, { purpose = 'drain' } = {}) {
  if (!['worker', 'drain', 'requeue'].includes(purpose)) throw new TypeError('Invalid delivery lease purpose');
  const { handle, info } = await lockFile(directory, true);
  try {
    if (!await flock(handle)) {
