    nativeStatus = { code: value.code, name: value.code === 0 ? 'OK' :
      (mapError({ code: value.code }).grpcCode ?? 'UNKNOWN') };
    resolveTerminal();
  };
  nativeCall.on('error', nativeError);
  nativeCall.once('status', status);
