  catch(error) {
    if(error.code!=='EEXIST'||!resume)throw new InputError(error.code==='EEXIST'?'OPERATION_HANDOFF_DESTINATION_EXISTS':'OPERATION_HANDOFF_DESTINATION_UNAVAILABLE');
