function localReference(reference, root) {
  if (typeof reference !== 'string' || !reference.startsWith('#')) return undefined;
  let fragment;
  try { fragment = decodeURIComponent(reference.slice(1)); } catch { return undefined; }
  if (!fragment) return root;
