        return respond(res, 404, { error: 'CONTROL_ROUTE_NOT_FOUND' });
      if (!/^application\/json(?:\s*;|$)/i.test(req.headers['content-type'] ?? ''))
        return respond(res, 415, { error: 'JSON_CONTENT_TYPE_REQUIRED' });
