  const rawEvidence = await readPrivate(plan.evidencePath, 2 * 1024 * 1024);
  let evidence;
  try { evidence = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(rawEvidence)); }
  catch { throw new InputError('OBJECT_NATIVE_EVIDENCE_INVALID'); }
