    need(previous.host === hostname(), 'OBJECT_LOCK_OTHER_HOST');
    need(await deadProcess(previous), 'OBJECT_SESSION_RUNNING');
    await releaseLease(directory, previous, 'DEAD_OWNER_RECOVERY');
