        type:file.name.endsWith('.json')?'application/json':file.name.endsWith('.html')?'text/html':
          file.name.endsWith('.md')?'text/markdown':'application/octet-stream'};
    },
    async close() {
      if(closePromise)return closePromise;
      closing=true;
      closePromise=(async()=>{
        const pending=[...active.values()];
        for(const task of pending){task.controller.abort();task.stream?.destroy?.(problem('SF49_DELIVERY_CLOSING'));}
        await Promise.allSettled(pending.map(task=>task.promise));
      })();
      return closePromise;
    }
  };
  return service;
}

// MIT. Existing private operations listener -> original SF98 event recovery.
import { randomBytes, timingSafeEqual } from 'node:crypto';
import { deliveryEvent, deliveryPage } from './delivery-view.mjs';
import { inspectDelivery, requeueDelivery } from '../../sf98-merchant-delivery/delivery-recovery.mjs';

const BASE = '/api/delivery';
const SCHEMA = 'stellar-forge.sf98.delivery-desk.v1';
const failure = (code,status=400) => Object.assign(new Error(code),{code,status});
const sameToken = (value,expected) => typeof value === 'string' && typeof expected === 'string' &&
  Buffer.byteLength(value) === Buffer.byteLength(expected) && timingSafeEqual(Buffer.from(value),Buffer.from(expected));
const plain = value => value !== null && typeof value === 'object' && !Array.isArray(value) &&
  [Object.prototype,null].includes(Object.getPrototypeOf(value));

function query(url,keys) {
  const actual = [...url.searchParams.keys()];
  if (actual.length !== new Set(actual).size || actual.some(key => !keys.includes(key)))
    throw failure('DELIVERY_QUERY_INVALID');
  return Object.fromEntries(url.searchParams);
}

async function input(req,maxBytes=2048) {
  if (!/^application\/json(?:\s*;\s*charset=utf-8)?$/i.test(req.headers['content-type'] ?? ''))
    throw failure('DELIVERY_JSON_REQUIRED',415);
  const length = req.headers['content-length'];
  if (length !== undefined && (!/^\d+$/.test(length) || Number(length) > maxBytes))
    throw failure('DELIVERY_INPUT_TOO_LARGE',413);
  return await new Promise((resolve,reject) => {
    let size = 0,done = false; const chunks = [];
    const finish = (error,value) => { if (done) return; done = true; chunks.length = 0; error ? reject(error) : resolve(value); };
    req.on('data',chunk => { if (done) return; size += chunk.length;
      if (size > maxBytes) return finish(failure('DELIVERY_INPUT_TOO_LARGE',413)); chunks.push(chunk); });
    req.once('aborted',() => finish(failure('DELIVERY_INPUT_INTERRUPTED')));
    req.once('error',() => finish(failure('DELIVERY_INPUT_INTERRUPTED')));
    req.once('end',() => { if (done) return;
      try { finish(null,JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(Buffer.concat(chunks)))); }
      catch { finish(failure('DELIVERY_JSON_INVALID')); } });
  });
}

/** A receiver-workspace owner can provide recovery(input), wrapping the SAME
 * requeueDelivery helper with owned pause/resume and pinned profile handling.
 * The default performs that helper directly when the original lease is free. */
export function createDeliveryDesk(outbox,{enabled=true,recovery=null,incidents=null,receiverWorkspace=null,clock=Date.now}={}) {
  if (typeof enabled !== 'boolean' || recovery !== null && typeof recovery !== 'function')
    throw new TypeError('Invalid native delivery controller');
  const available = typeof outbox?.rows === 'function' && typeof outbox?.requeue === 'function';
  const controlsEnabled = enabled && available;
  const token = controlsEnabled ? randomBytes(32).toString('hex') : null;
  const pending = new Set(); let closing = false;
  async function respond(req,origins) {
    if (closing) throw failure('DELIVERY_DESK_CLOSING',503);
    const url = new URL(req.url,'http://127.0.0.1');
    if ([BASE+'/requeue',BASE+'/incident/ack'].includes(url.pathname)) {
      if (req.method !== 'POST') return {status:405,body:{error:'DELIVERY_POST_REQUIRED'},headers:{allow:'POST'}};
      if (!controlsEnabled || !origins.has(req.headers.origin) || !sameToken(req.headers['x-delivery-control'],token))
        throw failure('DELIVERY_CONTROL_REQUIRED',403);
      query(url,[]);
      if(url.pathname===BASE+'/incident/ack') {
        if(!incidents)throw failure('DELIVERY_INCIDENTS_UNAVAILABLE',404);
        const command=await input(req,8192);
        if(!plain(command) || Object.keys(command).sort().join(',')!=='by,expectedRevision,id,notes')
          throw failure('DELIVERY_INCIDENT_ACK_INVALID');
        return {status:200,body:await incidents.acknowledge(command)};
      }
      const command = await input(req);
      if (!plain(command) || Object.keys(command).sort().join(',') !== 'expectedRevision,id' ||
          !/^[a-f0-9]{64}$/.test(command.id ?? '') || !/^[a-f0-9]{64}$/.test(command.expectedRevision ?? ''))
        throw failure('DELIVERY_RECOVERY_INPUT_INVALID');
      const result = await (recovery ? recovery(command) : requeueDelivery(outbox,command));
      return {status:200,body:{schema:SCHEMA,recovery:result}};
    }
    if (!['GET','HEAD'].includes(req.method)) return {status:405,body:{error:'DELIVERY_READ_ONLY'},headers:{allow:'GET, HEAD'}};
    if (url.pathname === BASE+'/control') {
      query(url,[]);
      return {status:200,body:{schema:SCHEMA,available,controlsEnabled,managedWorker:recovery !== null,
        receiverWorkspace,incidentMonitoring:incidents!==null,
        semantics:'Requeue the selected original notification after receiver repair; no payment or resource purchase.'}};
    }
    if(url.pathname===BASE+'/incidents') {
      const options=query(url,['state','cursor','limit']);
      if(!incidents)return {status:200,body:{schema:'stellar-forge.sf93.merchant-incident-view.v1',available:false}};
      if(options.limit!==undefined && !/^(?:[1-9]\d?|100)$/.test(options.limit))throw failure('DELIVERY_INCIDENT_QUERY_INVALID');
      return {status:200,body:await incidents.read({...options,limit:options.limit===undefined?25:Number(options.limit)})};
    }
    if(url.pathname===BASE+'/incident') {
      const {id}=query(url,['id']);
      if(!incidents)throw failure('DELIVERY_INCIDENTS_UNAVAILABLE',404);
      return {status:200,body:await incidents.detail(id)};
    }
    if (!available) throw failure('DELIVERY_OUTBOX_UNAVAILABLE',404);
    if (url.pathname === BASE+'/events') {
      const options = query(url,['state','cursor','limit','routeId']);
      if (options.limit !== undefined && !/^(?:[1-9]\d?|100)$/.test(options.limit)) throw failure('DELIVERY_QUERY_INVALID');
      return {status:200,body:deliveryPage(await outbox.rows(),{...options,
        limit:options.limit === undefined ? 25 : Number(options.limit),now:clock()})};
    }
    if (url.pathname === BASE+'/event') {
      const {id} = query(url,['id']);
      const original = await inspectDelivery(outbox,id);
      return {status:200,body:{schema:SCHEMA,event:deliveryEvent(original.row,{now:clock()}),
        revision:original.revision,requeueAvailable:controlsEnabled && original.row.state?.state === 'EXHAUSTED',
        managedWorker:recovery !== null}};
    }
    throw failure('DELIVERY_ROUTE_NOT_FOUND',404);
  }
  return Object.freeze({
    controlFragment:token ? 'control='+token : null,
    accepts:value => { try { return ['/control','/events','/event','/requeue','/incidents','/incident','/incident/ack'].some(tail =>
      new URL(value,'http://127.0.0.1').pathname === BASE+tail); } catch { return false; } },
    dispatch(req,origins) {
      const call = respond(req,origins).catch(error => ({
        status:Number.isInteger(error.status) && error.status >= 400 && error.status <= 599 ? error.status :
          error instanceof TypeError ? 400 : error instanceof RangeError ? 409 : 503,
        body:{error:error.code==='SF98_DELIVERY_BUSY'?'DELIVERY_WORKER_ACTIVE':
          typeof error.code === 'string' && /^DELIVERY_[A-Z_]+$/.test(error.code) ? error.code :
          error instanceof TypeError ? 'DELIVERY_QUERY_INVALID' : 'DELIVERY_STATE_UNAVAILABLE'},
      }));
      pending.add(call); call.finally(() => pending.delete(call)); return call;
    },
    async close() { closing = true; await Promise.allSettled([...pending]); },
  });
}

// MIT. Single merchant-scoped integration of the published SF52 and SF68 original HTTP diagnostics.
// No signing, credentialed requests, paid HTTP retry, or settlement operations.
import {writeFile} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {resolve} from 'node:path';
import {diagnose, requireEndpoint} from '../sf52-merchant-visibility/diagnose.mjs';
import {probe} from '../sf68-browser-payment-readiness/audit.mjs';
import {supportsSellerMethod} from '../sf30-seller-sdk/http-methods.mjs';

const VALUE_FLAGS = new Set(['--resource','--catalog','--origin','--network','--pay-to','--method','--out']);
const SWITCH_FLAGS = new Set(['--credentialed','--allow-loopback','--help']);
const HELP = [
  'SF70 merchant one-pass intake (read-only, Node 22+)',
  'node run.mjs --resource https://seller.example/paid --catalog https://facilitator.example/discovery/resources',
  '  --origin https://buyer.example --network stellar:testnet --pay-to G... [--method GET|HEAD|POST|PUT|PATCH|DELETE]',
  '  [--credentialed] [--out private.json]',
  'For local original HTTP fixtures only: --allow-loopback with literal http://127.0.0.1 URLs.',
  'Performs original catalog GET pages; GET/OPTIONS browser checks only where GET is a relevant advertised operation. Never signs or pays.'
].join('\n');

export function parseArgs(argv) {
  const values = new Map(), switches = new Set();
  for (let i=0;i<argv.length;i++) {
    const key = argv[i];
    if (SWITCH_FLAGS.has(key)) {
      if (switches.has(key)) throw new TypeError('Duplicate option: '+key);
      switches.add(key);
    } else if (VALUE_FLAGS.has(key)) {
      if (values.has(key) || !argv[i+1] || argv[i+1].startsWith('--'))
        throw new TypeError('Missing or repeated option: '+key);
      values.set(key,argv[++i]);
    } else throw new TypeError('Unknown option: '+key);
  }
  if (switches.has('--help')) {
    if (switches.size!==1 || values.size) throw new TypeError('--help must be alone');
    return {help:true};
  }
  for (const field of ['--resource','--catalog','--origin','--network','--pay-to']) {
    if (!values.has(field)) throw new TypeError('Required: '+field);
  }
  const allowLoopback=switches.has('--allow-loopback');
  const resource=requireEndpoint(values.get('--resource'),{allowLoopback});
  const catalog=requireEndpoint(values.get('--catalog'),{allowLoopback});
  const browser=requireEndpoint(values.get('--origin'),{allowLoopback});
  if (browser.pathname!=='/' || browser.search || browser.hash)
    throw new TypeError('Buyer origin must have no path or query');
  if (resource.origin===browser.origin) throw new TypeError('Buyer origin must differ from seller');
  const network=values.get('--network');
  if (!/^stellar:[a-z0-9-]{2,32}$/.test(network)) throw new TypeError('Expected exact stellar:* network');
  const payTo=values.get('--pay-to');
  if (!payTo.trim() || payTo!==payTo.trim() || payTo.length>256)
    throw new TypeError('Invalid seller payment recipient');
  const method=values.get('--method')||'GET';
  if (!supportsSellerMethod(method))
    throw new TypeError('Unsupported intended buyer retry method');
  const out=values.get('--out');
  if (out && out.length>2048) throw new TypeError('Report path too long');
  return {resourceUrl:resource.toString(),catalogUrl:catalog.toString(),origin:browser.origin,
    network,payTo,method,credentialed:switches.has('--credentialed'),allowLoopback,out};
}

export function combine({seller,browser,error,config,observedAt}) {
  const findings=[];
  const add=(severity,code,action)=>findings.push({severity,code,action});
  const nonGetOnly=seller.sellerDiscovery.state==='CATALOG_NON_GET_ONLY';
  if (nonGetOnly)
    add('UNKNOWN','NON_GET_OR_MCP_ONLY',
      'Source catalog lists non-GET HTTP or MCP operations. An unpaid GET is not a valid checkout test of this route; original advertised operation needs its own authorized verification.');
  else if (seller.sellerDiscovery.state!=='UNPAID_402_BAZAAR_VISIBLE')
    add('HIGH','SELLER_UNPAID_DISCOVERY',
      'Verify the advertised unpaid GET operation returns a valid 402 PAYMENT-REQUIRED with Bazaar extension.');
  if (!seller.catalog.complete)
    add('UNKNOWN','CATALOG_NOT_EXHAUSTIVE',
      'Finish actual facilitator pagination or resolve the reported provider error before claiming listing absence.');
  if (seller.verdict==='INCONCLUSIVE_CATALOG') {
    if (seller.catalog.complete) add('UNKNOWN','CATALOG_INCONCLUSIVE','Review original SF52 catalog and provider response.');
  } else if (seller.verdict!=='LISTED')
    add('HIGH','CATALOG_ROUTE_MISMATCH',
      'Confirm the identical resource operation has a single accepted Stellar network and payTo in the facilitator listing.');
  else if (seller.catalog.matchingEvidence.desiredPaymentRouteFound!==true)
    add('HIGH','CATALOG_PAIRED_TERMS',
      'Require network and recipient on the same accepted payment alternative.');
  if (!browser && nonGetOnly) add('UNKNOWN','BROWSER_METHOD_UNASSESSED',
    'SF68 GET/OPTIONS audit is not a checkout test for a confirmed non-GET/MCP-only catalog offer. Assess the actual authorized operation in a separate browser-aware integration.');
  else if (!browser) add('UNKNOWN','BROWSER_HTTP_UNAVAILABLE',
    'Repeat the original unpaid browser-origin GET and OPTIONS; '+String(error||'request failed').slice(0,200));
  else if (browser.status!=='READABLE_402_AND_PREFLIGHT_READY')
    for (const f of browser.findings)
      add(f.severity==='HIGH'?'HIGH':'UNKNOWN','BROWSER_'+f.code,f.repair);
  const state=findings.some(f=>f.severity==='HIGH')?'REMEDIATION_REQUIRED':
    findings.length?'INCONCLUSIVE':'UNPAID_DISCOVERY_AND_BROWSER_READY';
  return {
    schema:'stellar-forge.merchant-intake.v1',state,observedAt,
    scope:{resource:config.resourceUrl,catalog:config.catalogUrl,buyerOrigin:config.origin,
      network:config.network,payTo:config.payTo,intendedRetryMethod:config.method,
      browserCredentialed:config.credentialed===true},
    findings,
    originals:{sellerCatalog:seller,browserReadiness:browser??null,browserError:error??null},
    safeguards:{walletCalls:0,paidRequests:0,settlementConfirmed:false,
      buyerAuthorizationConfirmed:false,sellerPermissionConfirmed:false,
      description:'Catalog GET pages plus GET/OPTIONS only when the original offer supports GET; no paid request, customer acceptance or settlement.'}
  };
}

export async function capture(config) {
  const observedAt=new Date().toISOString();
  // Preserve original implementations, including redirect/timeout and catalog pagination boundaries.
  const seller=await diagnose({resourceUrl:config.resourceUrl,catalogUrl:config.catalogUrl,
    network:config.network,payTo:config.payTo,allowLoopback:config.allowLoopback});
  let browser=null,error=null;
  // The genuine method-aware SF52 catalog can establish a POST/MCP-only offer.
  // Do not reintroduce a misleading unpaid GET or CORS diagnosis for that offer.
  if (seller.sellerDiscovery.state!=='CATALOG_NON_GET_ONLY') {
    try {
      browser=await probe({resource:config.resourceUrl,origin:config.origin,
        method:config.method,credentialed:config.credentialed});
    } catch (e) { error=String(e?.message||e).slice(0,200); }
  }
  return combine({seller,browser,error,config,observedAt});
}

export async function main(argv=process.argv.slice(2)) {
  const config=parseArgs(argv);
  if (config.help) {process.stdout.write(HELP+'\n');return;}
  const report=await capture(config);
  const json=JSON.stringify(report,null,2)+'\n';
  if (config.out) await writeFile(config.out,json,{flag:'wx',mode:0o600});
  process.stdout.write(json);
  if (report.state==='REMEDIATION_REQUIRED') process.exitCode=2;
  else if (report.state==='INCONCLUSIVE') process.exitCode=3;
}
if (process.argv[1] && resolve(process.argv[1])===fileURLToPath(import.meta.url)) {
  main().catch(e=>{process.stderr.write('SF70 merchant intake: '+String(e.message)+'\n');process.exitCode=1;});
}

// MIT. Complete operator export within an original SQLite read worker.
import { constants } from 'node:sqlite';

const fail = code => Object.assign(new Error(code), { code });
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const count = (value, low, high, code) => {
  if (!Number.isSafeInteger(value) || value < low || value > high) throw fail(code);
  return value;
};
const quote = name => '"' + name + '"';

export function sqliteExtractionOptions(query, supplied = {}) {
  if (!record(supplied) || Object.keys(supplied).some(key =>
    !['maxRows', 'maxBytes', 'maxRowBytes', 'timeoutMs', 'order'].includes(key)))
    throw fail('DATASET_EXTRACTION_OPTIONS_INVALID');
  const result = {
    maxRows: count(supplied.maxRows ?? 250000, 1, 1000000, 'DATASET_EXTRACTION_ROW_LIMIT'),
    maxBytes: count(supplied.maxBytes ?? 67108864, 1024, 268435456, 'DATASET_EXTRACTION_BYTE_LIMIT'),
    maxRowBytes: count(supplied.maxRowBytes ?? 1048576, 1024, 8388608, 'DATASET_EXTRACTION_ROW_BYTES'),
    timeoutMs: count(supplied.timeoutMs ?? 30000, 100, 300000, 'DATASET_EXTRACTION_TIMEOUT'),
  };
  if (!Array.isArray(supplied.order) || !supplied.order.length || supplied.order.length > query.columns.length)
    throw fail('DATASET_EXTRACTION_ORDER_REQUIRED');
  const names = new Set();
  result.order = supplied.order.map(item => {
    if (!record(item) || Object.keys(item).some(key => !['column', 'direction'].includes(key)) ||
        !query.columns.includes(item.column) || names.has(item.column) || !['asc', 'desc'].includes(item.direction))
      throw fail('DATASET_EXTRACTION_ORDER_INVALID');
    names.add(item.column); return { column: item.column, direction: item.direction };
  });
  return result;
}

function valueBytes(value) {
  if (value === null) return 0;
  if (value instanceof Uint8Array) return value.byteLength;
  if (typeof value === 'string' || typeof value === 'bigint') return Buffer.byteLength(String(value));
  if (typeof value === 'number' && Number.isFinite(value)) return Buffer.byteLength(String(value));
  throw fail('DATASET_EXTRACTION_ENCODING_CHANGED');
}

/** The worker holds this transaction while each row is acknowledged by the
 * parent's actual consumer. No materialized result array or fire-and-forget IPC. */
export async function readSqliteDataset(database, query, { name, parameters, options, onRow }) {
  const limits = sqliteExtractionOptions(query, options);
  let rowCount = 0, sourceBytes = 0, authorizer = false, transaction;
  const priorLength = database.limits?.length;
  try {
    if (database.isTransaction) throw fail('DATASET_TRANSACTION_ALREADY_OPEN');
    database.exec('BEGIN');
    const settings = {
      queryOnly: database.prepare('PRAGMA query_only').get().query_only,
      readUncommitted: database.prepare('PRAGMA read_uncommitted').get().read_uncommitted,
      journalMode: database.prepare('PRAGMA journal_mode').get().journal_mode,
      schemaVersion: database.prepare('PRAGMA schema_version').get().schema_version,
      dataVersion: database.prepare('PRAGMA data_version').get().data_version,
      sqliteVersion: database.prepare('SELECT sqlite_version() AS version').get().version,
    };
    // Force the database read snapshot before yielding any source values.
    database.prepare('SELECT COUNT(*) FROM sqlite_schema').get();
    if (settings.queryOnly !== 1 || settings.readUncommitted !== 0 || !database.isTransaction)
      throw fail('DATASET_EXTRACTION_TRANSACTION_INVALID');
    transaction = { readOnly: true, isolation: 'SERIALIZABLE', scope: 'single-connection-read-transaction',
      startedAt: new Date().toISOString(), ...settings };
    if (priorLength !== undefined) database.limits.length = Math.min(priorLength, limits.maxRowBytes);
    if (typeof database.setAuthorizer === 'function') {
      database.setAuthorizer((code, _first, second, dbName) => {
        if (code === constants.SQLITE_SELECT || code === constants.SQLITE_RECURSIVE) return constants.SQLITE_OK;
        if (code === constants.SQLITE_READ && dbName === 'main') return constants.SQLITE_OK;
        if (code === constants.SQLITE_FUNCTION && second !== 'load_extension') return constants.SQLITE_OK;
        return constants.SQLITE_DENY;
      });
      authorizer = true;
    }
    const ordering = limits.order.map(item => quote(item.column) + ' ' + item.direction.toUpperCase() + ' NULLS LAST').join(', ');
    const sql = 'SELECT ' + query.columns.map(quote).join(', ') + '\nFROM (\n' + query.sql +
      '\n) AS "__sf30_source" ORDER BY ' + ordering + ' LIMIT ' + (limits.maxRows + 1);
    const statement = database.prepare(sql);
    if (statement.sourceSQL.trim() !== sql) throw fail('QUERY_MULTIPLE_STATEMENTS');
    statement.setAllowBareNamedParameters(false); statement.setReadBigInts(true);
    const columnTypes = statement.columns().map(item => ({ name: item.name,
      declaredType: item.type, sourceColumn: item.column, sourceTable: item.table, database: item.database }));
    if (columnTypes.length !== query.columns.length || columnTypes.some((item, index) => item.name !== query.columns[index]))
      throw fail('QUERY_PROJECTION_CHANGED');
    for (const row of statement.iterate(parameters)) {
      if (rowCount >= limits.maxRows) throw fail('DATASET_EXTRACTION_TOO_MANY_ROWS');
      const rowBytes = query.columns.reduce((total, column) => total + valueBytes(row[column]), 0);
      if (rowBytes > limits.maxRowBytes) throw fail('DATASET_EXTRACTION_ROW_TOO_LARGE');
      sourceBytes += rowBytes;
      if (sourceBytes > limits.maxBytes) throw fail('DATASET_EXTRACTION_TOO_MANY_BYTES');
      await onRow(row, columnTypes, { rowCount: rowCount + 1, sourceBytes });
      rowCount++;
    }
    if (authorizer) { database.setAuthorizer(null); authorizer = false; }
    database.exec('COMMIT');
    return { schema: 'stellar-forge.sqlite-dataset-extraction.v1', query: name, rowCount, sourceBytes,
      columns: [...query.columns], columnTypes, transaction: { ...transaction, completedAt: new Date().toISOString() },
      valueEncoding: 'sqlite-native', nullEncoding: 'json-null', order: limits.order };
  } finally {
    if (authorizer) database.setAuthorizer(null);
    if (database.isTransaction) database.exec('ROLLBACK');
    if (priorLength !== undefined) database.limits.length = priorLength;
  }
}

/**
 * SF96: observe original SF30 seller routes in its CHALLENGE_ONLY runtime.
